"use client"

/**
 * CI Checks Live. The view reads a transport. The token stays on the server.
 * Merge is off unless `mergeEnabled` is set. The checks panel starts closed.
 * Idea only, no license. Demo data is fictional when the host passes it.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { createAgentFixPort, estimateProgress, notifyCheckFailed, type AgentFixEvent, type AgentFixPort, type NormalizedCheck } from "@/lib/ci-checks"
import { AgentFixTimeline, agentFixTimelineLabels, agentFixTimelineLabelsEs, type FixStep } from "@/components/ui/agent-fix-timeline"
import { ChecksPanel, checksPanelLabels, checksPanelLabelsEs, type CheckItem } from "@/components/ui/checks-panel"
import { MergeButton, mergeButtonLabels, mergeButtonLabelsEs, type MergePhase } from "@/components/ui/merge-button"
import { PrCreateCard, prCreateCardLabels, prCreateCardLabelsEs, type CommitNode } from "@/components/ui/pr-create-card"
import { useReducedMotion } from "../ui/use-reduced-motion"
import { useCiChecks, type CiTransport } from "@/hooks/use-ci-checks"

export type CiChecksLiveLabels = {
  locale: "es" | "en"
  loading: string
  missing: string
  mergeOffPending: string
  mergeOffReady: string
  estimatedNote: string
  region: string
}

export const ciChecksLiveLabels: CiChecksLiveLabels = {
  locale: "en",
  loading: "Loading checks.",
  missing: "No pull request yet.",
  mergeOffPending: "Merge is off until the checks finish.",
  mergeOffReady: "Merge is off. The checks have passed.",
  estimatedNote: "Bar times are estimated from history or elapsed time.",
  region: "CI checks",
}

export const ciChecksLiveLabelsEs: CiChecksLiveLabels = {
  locale: "es",
  loading: "Cargando comprobaciones.",
  missing: "Todavía no hay pull request.",
  mergeOffPending: "La fusión está apagada. Falta que terminen las comprobaciones.",
  mergeOffReady: "La fusión está apagada. Las comprobaciones ya pasaron.",
  estimatedNote: "Los tiempos de las barras son estimados, a partir del historial o del tiempo transcurrido.",
  region: "Comprobaciones de CI",
}

export type CiChecksLiveProps = {
  transport: CiTransport
  mergeEnabled?: boolean
  pollMs?: number
  agent?: AgentFixPort
  onCheckFailed?: (check: { id: string; name: string; url: string | null }) => void
  variant?: "rail" | "compact"
  labels?: CiChecksLiveLabels
  className?: string
  historyMs?: Readonly<Record<string, readonly number[]>>
  now?: number
}

export function CiChecksLive({
  transport,
  mergeEnabled = false,
  pollMs = 0,
  agent,
  onCheckFailed,
  variant = "rail",
  labels = ciChecksLiveLabelsEs,
  className,
  historyMs = {},
  now,
}: CiChecksLiveProps) {
  const reduced = useReducedMotion()
  const state = useCiChecks({ transport, pollMs })
  const [panelOpen, setPanelOpen] = React.useState(false)
  const [outcome, setOutcome] = React.useState<"idle" | "merging" | "merged" | "rejected">("idle")
  const [mergeReason, setMergeReason] = React.useState<string | undefined>()
  const [tick, setTick] = React.useState(0)
  const seenFailures = React.useRef(new Set<string>())
  const localPort = React.useMemo(() => createAgentFixPort(), [])
  const port = agent ?? localPort
  const events = port.snapshot()
  const mergePhase: MergePhase = !mergeEnabled
    ? "disabled"
    : outcome === "idle"
      ? ready(state.snapshot, true) ? "ready" : "disabled"
      : outcome

  React.useEffect(() => port.subscribe(() => setTick((value) => value + 1)), [port])

  React.useEffect(() => {
    const failed = state.snapshot?.checks.filter((check) => check.status === "failed") ?? []
    for (const check of failed) {
      if (seenFailures.current.has(check.id)) continue
      seenFailures.current.add(check.id)
      notifyCheckFailed(onCheckFailed, { id: check.id, name: check.name, url: check.url })
    }
  }, [onCheckFailed, state.snapshot])

  const locale = labels.locale
  const pull = state.snapshot?.pull
  const checks = state.snapshot?.checks ?? []
  const clock = now ?? 0
  const rows = checks.map((check) => toRow(check, clock, historyMs[check.name] ?? []))
  const anyEstimated = rows.some((row) => row.estimated)

  async function confirmMerge() {
    if (!mergeEnabled || !pull) return
    setOutcome("merging")
    const result = await state.merge({ confirmed: true, grantedBy: "reader" })
    if (result.ok) {
      setOutcome("merged")
      setMergeReason(undefined)
      return
    }
    setOutcome("rejected")
    setMergeReason(result.message)
  }

  return (
    <section
      aria-label={labels.region}
      data-testid="ci-checks-live"
      data-motion={reduced ? "reduced" : "full"}
      data-events={tick}
      className={cn("flex w-full min-w-0 flex-col gap-4", className)}
    >
      <p role="status" aria-live="polite" className="sr-only">
        {state.loading ? labels.loading : state.error?.message ?? (pull ? `${state.snapshot?.passed ?? 0} / ${state.snapshot?.total ?? 0}` : labels.missing)}
      </p>
      {state.loading && !pull ? <p className="text-sm text-muted-foreground">{labels.loading}</p> : null}
      {state.error ? <p role="alert" className="text-sm text-destructive">{state.error.message}</p> : null}
      {!pull && !state.loading && !state.error ? <p className="text-sm text-muted-foreground">{labels.missing}</p> : null}
      {pull ? (
        <PrCreateCard
          open
          title={pull.title}
          number={pull.number}
          state={pull.state === "merged" ? "merged" : pull.state === "closed" ? "closed" : "open"}
          diffStat={{ add: pull.additions, del: pull.deletions }}
          commits={pull.commits.map(toCommit)}
          variant={variant}
          now={clock}
          locale={locale === "es" ? "es-MX" : "en"}
          labels={locale === "en" ? prCreateCardLabels : prCreateCardLabelsEs}
        />
      ) : null}
      {pull ? (
        <ChecksPanel
          passed={state.snapshot?.passed ?? 0}
          total={state.snapshot?.total ?? 0}
          sha={pull.sha.slice(0, 7)}
          message={pull.title}
          checks={rows}
          open={panelOpen}
          onOpenChange={setPanelOpen}
          variant={variant}
          labels={locale === "en" ? checksPanelLabels : checksPanelLabelsEs}
        />
      ) : null}
      {anyEstimated ? <p className="text-xs text-muted-foreground">{labels.estimatedNote}</p> : null}
      {events.length > 0 ? (
        <AgentFixTimeline steps={events.map(toStep)} variant={variant} labels={locale === "en" ? agentFixTimelineLabels : agentFixTimelineLabelsEs} />
      ) : null}
      {pull ? (
        <MergeButton
          phase={mergeEnabled ? mergePhase : "disabled"}
          reason={mergeReason}
          {...(mergeEnabled ? {} : { statusLabel: mergeOffLabel(labels, ready(state.snapshot, true)) })}
          variant={variant}
          labels={locale === "en" ? mergeButtonLabels : mergeButtonLabelsEs}
          onMerge={() => void confirmMerge()}
        />
      ) : null}
    </section>
  )
}

function mergeOffLabel(labels: CiChecksLiveLabels, checksReady: boolean) {
  return checksReady ? labels.mergeOffReady : labels.mergeOffPending
}

function ready(snapshot: { checks: NormalizedCheck[]; total: number } | null, mergeEnabled: boolean) {
  if (!mergeEnabled || !snapshot || snapshot.total === 0) return false
  return snapshot.checks.every((check) => check.status === "passed" || check.status === "skipped")
}

function toRow(check: NormalizedCheck, now: number, history: readonly number[]): CheckItem {
  const estimate = estimateProgress({
    status: check.status,
    startedAt: check.startedAt,
    completedAt: check.completedAt,
    measuredDurationMs: check.durationMs,
    now,
    historyMs: history,
  })
  const row: CheckItem = {
    id: check.id,
    name: check.name,
    status: check.status,
    progress: estimate.progress,
    estimated: estimate.estimated,
  }
  if (estimate.durationMs != null) row.durationMs = estimate.durationMs
  if (check.url) row.url = check.url
  return row
}

function toCommit(commit: { sha: string; message: string; author: string; committedAt: string | null }): CommitNode {
  return {
    sha: commit.sha.slice(0, 7),
    message: commit.message,
    author: commit.author,
    timeLabel: "",
    ...(commit.committedAt ? { committedAt: commit.committedAt } : {}),
  }
}

function toStep(event: AgentFixEvent): FixStep {
  return {
    id: event.id,
    kind: event.kind,
    label: event.label,
    status: event.kind === "done" ? "done" : "done",
    files: event.files?.map((path) => ({ path })),
  }
}

"use client"

/**
 * Client store for CI Checks Live.
 * Talks to a transport the host provides. It has no token parameter and
 * never sets an Authorization header.
 */

import * as React from "react"

import type { CiError, NormalizedSnapshot } from "@/lib/ci-checks"

export type CiSnapshotResponse = {
  snapshot?: NormalizedSnapshot
  etag?: string | null
  statusEtag?: string | null
  waitMs?: number
  error?: CiError
  checkRunsNotModified?: boolean
  statusesNotModified?: boolean
}

export type CiTransport = {
  load: (input: { etag: string | null }) => Promise<{ status: number; body: CiSnapshotResponse | null; etag: string | null }>
  merge: (input: { confirmed: boolean; grantedBy?: string; sha: string }) => Promise<{ ok: boolean; message: string }>
}

export type UseCiChecks = {
  snapshot: NormalizedSnapshot | null
  error: CiError | null
  loading: boolean
  merge: (input: { confirmed: boolean; grantedBy?: string }) => Promise<{ ok: boolean; message: string }>
}

export function useCiChecks(options: { transport: CiTransport; pollMs?: number }): UseCiChecks {
  const { transport, pollMs = 0 } = options
  const [snapshot, setSnapshot] = React.useState<NormalizedSnapshot | null>(null)
  const [error, setError] = React.useState<CiError | null>(null)
  const [loading, setLoading] = React.useState(true)
  const etag = React.useRef<string | null>(null)
  const transportRef = React.useRef(transport)

  React.useEffect(() => {
    transportRef.current = transport
  }, [transport])

  React.useEffect(() => {
    let stopped = false
    async function tick() {
      const result = await transportRef.current.load({ etag: etag.current })
      if (stopped) return
      if (result.etag) etag.current = result.etag
      if (result.status === 304) {
        setLoading(false)
        return
      }
      if (result.body?.error) setError(result.body.error)
      else setError(null)
      if (result.body?.snapshot) setSnapshot(result.body.snapshot)
      setLoading(false)
    }
    void tick()
    if (pollMs <= 0) return () => {
      stopped = true
    }
    const timer = window.setInterval(() => void tick(), pollMs)
    return () => {
      stopped = true
      window.clearInterval(timer)
    }
  }, [pollMs])

  const merge = React.useCallback(async (input: { confirmed: boolean; grantedBy?: string }) => {
    const sha = snapshot?.pull.sha ?? ""
    return transportRef.current.merge({ ...input, sha })
  }, [snapshot?.pull.sha])

  return { snapshot, error, loading, merge }
}

/** Browser transport. Relative URL only. No Authorization header is set. */
export function createHttpTransport(endpoint: string, fetchImpl: typeof fetch = globalThis.fetch): CiTransport {
  return {
    async load({ etag }) {
      const headers: Record<string, string> = { accept: "application/json" }
      if (etag) headers["if-none-match"] = etag
      const response = await fetchImpl(endpoint, { method: "GET", headers, cache: "no-store" })
      if (response.status === 304) return { status: 304, body: null, etag: response.headers.get("etag") }
      const body = (await response.json()) as CiSnapshotResponse
      return { status: response.status, body, etag: response.headers.get("etag") }
    },
    async merge(input) {
      const response = await fetchImpl(endpoint, {
        method: "POST",
        headers: { accept: "application/json", "content-type": "application/json" },
        body: JSON.stringify({ confirmed: input.confirmed, grantedBy: input.grantedBy, sha: input.sha }),
        cache: "no-store",
      })
      const body = (await response.json()) as { message?: string; error?: { message?: string }; merged?: boolean }
      return { ok: response.ok && body.merged === true, message: body.error?.message ?? body.message ?? "" }
    },
  }
}

"use client"

import * as React from "react"

function subscribe(onStoreChange: () => void) {
  const query = window.matchMedia("(prefers-reduced-motion: reduce)")
  query.addEventListener("change", onStoreChange)
  return () => query.removeEventListener("change", onStoreChange)
}

function snapshot() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

/** True when the reader asked for reduced motion. False during SSR. */
export function useReducedMotion() {
  return React.useSyncExternalStore(subscribe, snapshot, () => false)
}

/**
 * Turns GitHub check runs and commit statuses into the catalog model.
 * Shapes follow the public REST docs, anonymized by the caller.
 * https://docs.github.com/en/rest/checks/runs
 * https://docs.github.com/en/rest/commits/statuses
 */

import type { CheckSource, CheckStatus, NormalizedCheck, NormalizedCommit, NormalizedPull, PullState } from "./types"

type UnknownRecord = Record<string, unknown>

function record(value: unknown): UnknownRecord | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null
  return value as UnknownRecord
}

function text(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value : null
}

function numberValue(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null
}

function durationBetween(startedAt: string | null, completedAt: string | null): number | null {
  if (!startedAt || !completedAt) return null
  const start = Date.parse(startedAt)
  const end = Date.parse(completedAt)
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return null
  return end - start
}

export function checkRunStatus(status: string | null, conclusion: string | null): CheckStatus {
  if (status === "queued") return "queued"
  if (status === "in_progress" || status === "pending" || status === "waiting" || status === "requested") return "running"
  if (status !== "completed") return "queued"
  if (conclusion === "success" || conclusion === "neutral") return "passed"
  if (conclusion === "skipped" || conclusion === "stale") return "skipped"
  if (conclusion === "cancelled") return "cancelled"
  return "failed"
}

export function commitStatusState(state: string | null): CheckStatus {
  if (state === "success") return "passed"
  if (state === "failure" || state === "error") return "failed"
  if (state === "pending") return "running"
  return "queued"
}

export function normalizeCheckRun(value: unknown): NormalizedCheck | null {
  const run = record(value)
  if (!run) return null
  const name = text(run.name)
  if (!name) return null
  const startedAt = text(run.started_at)
  const completedAt = text(run.completed_at)
  const id = numberValue(run.id)
  const output = record(run.output)
  return {
    id: id == null ? `check-run:${name}` : `check-run:${id}`,
    name,
    status: checkRunStatus(text(run.status), text(run.conclusion)),
    source: "check-run",
    startedAt,
    completedAt,
    durationMs: durationBetween(startedAt, completedAt),
    url: text(run.html_url) ?? text(run.details_url),
    description: text(output?.title) ?? text(output?.summary),
  }
}

export function normalizeCommitStatus(value: unknown): NormalizedCheck | null {
  const status = record(value)
  if (!status) return null
  const name = text(status.context)
  if (!name) return null
  const id = numberValue(status.id)
  const createdAt = text(status.created_at)
  const updatedAt = text(status.updated_at)
  return {
    id: id == null ? `status:${name}` : `status:${id}`,
    name,
    status: commitStatusState(text(status.state)),
    source: "commit-status",
    startedAt: createdAt,
    completedAt: updatedAt,
    durationMs: durationBetween(createdAt, updatedAt),
    url: text(status.target_url),
    description: text(status.description),
  }
}

/** Check runs win when the same name exists on both APIs. Status-only names stay. */
export function mergeChecks(checkRuns: readonly NormalizedCheck[], statuses: readonly NormalizedCheck[]): NormalizedCheck[] {
  const byName = new Map<string, NormalizedCheck>()
  for (const status of statuses) byName.set(status.name, status)
  for (const run of checkRuns) byName.set(run.name, run)
  return [...byName.values()]
}

export function normalizeCheckRunsPayload(payload: unknown): NormalizedCheck[] {
  const root = record(payload)
  const list = Array.isArray(payload) ? payload : root && Array.isArray(root.check_runs) ? root.check_runs : []
  return list.map(normalizeCheckRun).filter((check): check is NormalizedCheck => check != null)
}

export function normalizeStatusesPayload(payload: unknown): NormalizedCheck[] {
  const root = record(payload)
  const list = Array.isArray(payload) ? payload : root && Array.isArray(root.statuses) ? root.statuses : []
  return list.map(normalizeCommitStatus).filter((check): check is NormalizedCheck => check != null)
}

export function countPassed(checks: readonly NormalizedCheck[]) {
  return checks.filter((check) => check.status === "passed").length
}

function pullState(value: UnknownRecord): PullState {
  if (text(value.merged_at) || value.merged === true) return "merged"
  const state = text(value.state)
  if (state === "closed") return "closed"
  return "open"
}

export function normalizePull(payload: unknown): NormalizedPull | null {
  const pull = record(payload)
  if (!pull) return null
  const number = numberValue(pull.number)
  const title = text(pull.title)
  const head = record(pull.head)
  const base = record(pull.base)
  const sha = text(head?.sha)
  if (number == null || !title || !sha) return null
  const commits = Array.isArray(pull.commits) ? pull.commits.map(normalizeCommit).filter((commit): commit is NormalizedCommit => commit != null) : []
  return {
    number,
    title,
    state: pullState(pull),
    sha,
    message: text(head?.label) ?? title,
    baseRef: text(base?.ref) ?? "main",
    headRef: text(head?.ref) ?? "",
    additions: numberValue(pull.additions) ?? 0,
    deletions: numberValue(pull.deletions) ?? 0,
    commits,
  }
}

function normalizeCommit(value: unknown): NormalizedCommit | null {
  const commit = record(value)
  if (!commit) return null
  const nested = record(commit.commit)
  const sha = text(commit.sha)
  const message = text(nested?.message) ?? text(commit.message)
  if (!sha || !message) return null
  const author = record(nested?.author) ?? record(commit.author)
  const login = text(record(commit.author)?.login)
  return {
    sha,
    message: message.split("\n")[0] ?? message,
    author: login ?? text(author?.name) ?? "unknown",
    committedAt: text(author?.date) ?? text(commit.committed_at),
  }
}

export function isVercelStatus(check: NormalizedCheck) {
  return check.source === "commit-status" && /vercel/i.test(check.name)
}

export function sourceOf(check: NormalizedCheck): CheckSource {
  return check.source
}

/**
 * Bar progress is an estimate unless both timestamps exist.
 * Running checks use the median of earlier durations for that name,
 * or 60 seconds when there is no history. The UI must say "estimated".
 */

import type { CheckStatus } from "./types"

export const FALLBACK_DURATION_MS = 60_000
export const RUNNING_PROGRESS_CAP = 0.95

export function median(values: readonly number[]): number | null {
  const sorted = values.filter((value) => Number.isFinite(value) && value > 0).slice().sort((a, b) => a - b)
  if (sorted.length === 0) return null
  const mid = Math.floor(sorted.length / 2)
  const left = sorted[mid - 1]
  const right = sorted[mid]
  if (sorted.length % 2 === 1) return right ?? null
  if (left == null || right == null) return null
  return (left + right) / 2
}

export type ProgressEstimate = {
  progress: number
  estimated: boolean
  durationMs: number | null
}

export function estimateProgress(input: {
  status: CheckStatus
  startedAt?: string | null
  completedAt?: string | null
  measuredDurationMs?: number | null
  now: number
  historyMs?: readonly number[]
  fallbackMs?: number
}): ProgressEstimate {
  const measured = input.measuredDurationMs
  if (input.status === "queued") return { progress: 0, estimated: false, durationMs: null }
  if (input.status === "skipped" || input.status === "cancelled") {
    return { progress: 0, estimated: measured == null, durationMs: measured ?? null }
  }
  if (input.status === "passed" || input.status === "failed") {
    return { progress: 1, estimated: measured == null, durationMs: measured ?? null }
  }
  const started = input.startedAt ? Date.parse(input.startedAt) : NaN
  const elapsed = Number.isFinite(started) ? Math.max(0, input.now - started) : 0
  const typical = median(input.historyMs ?? []) ?? input.fallbackMs ?? FALLBACK_DURATION_MS
  const ratio = typical <= 0 ? RUNNING_PROGRESS_CAP : elapsed / typical
  return {
    progress: Math.min(RUNNING_PROGRESS_CAP, Math.max(0, ratio)),
    estimated: true,
    durationMs: elapsed,
  }
}

/**
 * Pure polling decisions. The caller performs the request.
 * Primary rate limit: remaining 0, wait until reset.
 * Secondary rate limit: Retry-After, or the documented error text.
 * https://docs.github.com/en/rest/using-the-rest-api/rate-limits-for-the-rest-api
 */

import type { CiError } from "./types"

export const DEFAULT_POLL_MS = 15_000

export type HeaderMap = Record<string, string | null | undefined>

export type PollDecision = {
  kind: "ok" | "not_modified" | "error"
  etag: string | null
  waitMs: number
  error: CiError | null
}

function header(headers: HeaderMap, name: string) {
  const target = name.toLowerCase()
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === target) return value ?? null
  }
  return null
}

export function pollRequestHeaders(etag: string | null): Record<string, string> {
  const headers: Record<string, string> = {
    accept: "application/vnd.github+json",
    "x-github-api-version": "2022-11-28",
  }
  if (etag) headers["if-none-match"] = etag
  return headers
}

function retryAfterMs(value: string | null, now: number): number | null {
  if (!value) return null
  const seconds = Number(value)
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000)
  const date = Date.parse(value)
  if (!Number.isFinite(date)) return null
  return Math.max(0, date - now)
}

export function isSecondaryRateLimit(status: number, body: string, headers: HeaderMap) {
  if (status !== 403 && status !== 429) return false
  if (header(headers, "retry-after")) return true
  return /secondary rate limit/i.test(body)
}

export function isPrimaryRateLimit(status: number, headers: HeaderMap) {
  if (status !== 403 && status !== 429) return false
  return header(headers, "x-ratelimit-remaining") === "0"
}

export function interpretPoll(input: {
  status: number
  headers?: HeaderMap
  body?: string
  now: number
  attempt?: number
  etagSent?: string | null
}): PollDecision {
  const headers = input.headers ?? {}
  const body = input.body ?? ""
  const etag = header(headers, "etag") ?? input.etagSent ?? null
  const attempt = input.attempt ?? 0
  const resetHeader = header(headers, "x-ratelimit-reset")
  const resetMs = resetHeader && Number.isFinite(Number(resetHeader)) ? Number(resetHeader) * 1000 - input.now : null
  const remaining = header(headers, "x-ratelimit-remaining")

  if (input.status === 304) {
    return { kind: "not_modified", etag, waitMs: coolDown(remaining, resetMs), error: null }
  }

  if (isSecondaryRateLimit(input.status, body, headers) && !isPrimaryRateLimit(input.status, headers)) {
    const waitMs = retryAfterMs(header(headers, "retry-after"), input.now) ?? 60_000
    return {
      kind: "error",
      etag,
      waitMs,
      error: {
        code: "secondary_rate_limited",
        message: "GitHub aplicó un límite secundario. Hay que esperar antes de volver a pedir.",
        retryAfterMs: waitMs,
      },
    }
  }

  if (isPrimaryRateLimit(input.status, headers)) {
    const waitMs = Math.max(0, resetMs ?? 60_000)
    return {
      kind: "error",
      etag,
      waitMs,
      error: {
        code: "rate_limited",
        message: "Se agotó el cupo de GitHub para esta hora.",
        retryAfterMs: waitMs,
      },
    }
  }

  if (input.status === 401) {
    return { kind: "error", etag, waitMs: 0, error: { code: "unauthorized", message: "GitHub rechazó la credencial.", retryAfterMs: null } }
  }
  if (input.status === 403) {
    return { kind: "error", etag, waitMs: 0, error: { code: "forbidden", message: messageOf(body) ?? "GitHub negó el acceso.", retryAfterMs: null } }
  }
  if (input.status === 404) {
    return { kind: "error", etag, waitMs: 0, error: { code: "not_found", message: "No está el pull request o el commit.", retryAfterMs: null } }
  }
  if (input.status === 422) {
    return { kind: "error", etag, waitMs: 0, error: { code: "invalid", message: messageOf(body) ?? "GitHub no aceptó la petición.", retryAfterMs: null } }
  }
  if (input.status >= 200 && input.status < 300) {
    return { kind: "ok", etag, waitMs: coolDown(remaining, resetMs), error: null }
  }

  const waitMs = Math.min(60_000, 1000 * 2 ** Math.min(attempt, 5))
  return {
    kind: "error",
    etag,
    waitMs,
    error: { code: "upstream", message: messageOf(body) ?? `GitHub respondió ${input.status}.`, retryAfterMs: waitMs },
  }
}

function coolDown(remaining: string | null, resetMs: number | null) {
  if (remaining != null && Number(remaining) < 2 && resetMs != null && resetMs > 0) return resetMs
  return DEFAULT_POLL_MS
}

function messageOf(body: string) {
  try {
    const parsed = JSON.parse(body) as { message?: unknown; errors?: { message?: unknown }[] }
    if (typeof parsed.message === "string" && parsed.message && parsed.message !== "Validation Failed") {
      const detail = parsed.errors?.map((error) => error.message).filter((item): item is string => typeof item === "string")
      return detail && detail.length > 0 ? `${parsed.message}: ${detail.join(" ")}` : parsed.message
    }
    const detail = parsed.errors?.map((error) => error.message).filter((item): item is string => typeof item === "string")
    if (detail && detail.length > 0) return detail.join(" ")
  } catch {
    return null
  }
  return null
}

/**
 * GitHub paginates check runs at 100 per page and points at the next page
 * with a Link header. Parsing that header is pure. Walking the pages takes
 * an injected fetch so this file still does not open a socket itself.
 * https://docs.github.com/en/rest/using-the-rest-api/using-pagination-in-the-rest-api
 */

import { normalizeCheckRunsPayload } from "./normalize"
import type { CiError, NormalizedCheck } from "./types"

export function nextLink(header: string | null | undefined): string | null {
  if (!header) return null
  for (const part of header.split(",")) {
    const url = part.match(/<([^>]+)>/)
    const rel = part.match(/rel="?([^";]+)"?/i)
    if (url?.[1] && rel?.[1]?.toLowerCase() === "next") return url[1]
  }
  return null
}

export type CheckRunPage = {
  status: number
  body: string
  link: string | null
  error: CiError | null
}

export async function collectCheckRuns(input: {
  firstUrl: string
  fetchPage: (url: string) => Promise<CheckRunPage>
  maxPages?: number
}): Promise<{ checks: NormalizedCheck[]; pages: number; error: CiError | null }> {
  const maxPages = input.maxPages ?? 20
  const checks: NormalizedCheck[] = []
  let url: string | null = input.firstUrl
  let pages = 0
  while (url && pages < maxPages) {
    const page = await input.fetchPage(url)
    pages += 1
    if (page.error) return { checks, pages, error: page.error }
    checks.push(...normalizeCheckRunsPayload(parse(page.body)))
    url = nextLink(page.link)
  }
  return { checks, pages, error: null }
}

function parse(body: string): unknown {
  try {
    return JSON.parse(body) as unknown
  } catch {
    return null
  }
}

/**
 * Verifies X-Hub-Signature-256 and reads check_run, check_suite, and status.
 * https://docs.github.com/en/webhooks/using-webhooks/validating-webhook-deliveries
 * The HMAC function is injected so this file does not do I/O.
 */

import { normalizeCheckRun, normalizeCommitStatus } from "./normalize"
import type { NormalizedCheck } from "./types"

export type Sha256Hmac = (secret: string, body: string) => string | Promise<string>

export type WebhookResult =
  | { ok: true; ignored: true; event: string }
  | { ok: true; ignored: false; event: string; action: string | null; sha: string | null; checks: NormalizedCheck[] }
  | { ok: false; error: "bad_signature" | "unsupported" }

export function timingSafeEqualString(left: string, right: string) {
  const length = Math.max(left.length, right.length)
  let diff = left.length === right.length ? 0 : 1
  for (let index = 0; index < length; index += 1) {
    const a = left.charCodeAt(index) || 0
    const b = right.charCodeAt(index) || 0
    diff |= a ^ b
  }
  return diff === 0
}

export async function verifyGithubSignature(input: {
  rawBody: string
  signatureHeader: string | null
  secret: string
  hmac: Sha256Hmac
}) {
  const header = input.signatureHeader?.trim() ?? ""
  if (!header.startsWith("sha256=")) return false
  const provided = header.slice("sha256=".length)
  const digest = await input.hmac(input.secret, input.rawBody)
  const expected = digest.startsWith("sha256=") ? digest.slice("sha256=".length) : digest
  if (!/^[0-9a-f]+$/i.test(provided) || !/^[0-9a-f]+$/i.test(expected)) return false
  return timingSafeEqualString(provided.toLowerCase(), expected.toLowerCase())
}

export async function readWebhook(input: {
  event: string | null
  rawBody: string
  signatureHeader: string | null
  secret: string
  hmac: Sha256Hmac
}): Promise<WebhookResult> {
  const valid = await verifyGithubSignature(input)
  if (!valid) return { ok: false, error: "bad_signature" }
  let payload: unknown
  try {
    payload = JSON.parse(input.rawBody) as unknown
  } catch {
    return { ok: false, error: "unsupported" }
  }
  const event = input.event ?? ""
  if (event !== "check_run" && event !== "check_suite" && event !== "status") {
    return { ok: true, ignored: true, event }
  }
  const root = payload && typeof payload === "object" ? (payload as Record<string, unknown>) : {}
  const action = typeof root.action === "string" ? root.action : null
  if (event === "check_run") {
    const check = normalizeCheckRun(root.check_run)
    const sha = nestedSha(root.check_run)
    return { ok: true, ignored: false, event, action, sha, checks: check ? [check] : [] }
  }
  if (event === "status") {
    const check = normalizeCommitStatus(root)
    const sha = typeof root.sha === "string" ? root.sha : null
    return { ok: true, ignored: false, event, action, sha, checks: check ? [check] : [] }
  }
  const suite = root.check_suite && typeof root.check_suite === "object" ? (root.check_suite as Record<string, unknown>) : null
  const runs = suite && Array.isArray(suite.check_runs) ? suite.check_runs : []
  const checks = runs.map(normalizeCheckRun).filter((check): check is NormalizedCheck => check != null)
  const sha = suite && typeof suite.head_sha === "string" ? suite.head_sha : null
  return { ok: true, ignored: false, event, action, sha, checks }
}

function nestedSha(value: unknown) {
  if (!value || typeof value !== "object") return null
  const head = (value as { head_sha?: unknown }).head_sha
  if (typeof head === "string") return head
  const checkSuite = (value as { check_suite?: { head_sha?: unknown } }).check_suite
  return checkSuite && typeof checkSuite.head_sha === "string" ? checkSuite.head_sha : null
}

/**
 * Merge stays off unless the host enables it.
 * Without an explicit confirmation the send function is not called.
 */

import type { ApprovalGate, MergeApproval } from "./approval"
import type { CiError } from "./types"

export type MergeDecision = {
  callApi: boolean
  error: CiError | null
}

export function decideMerge(input: { mergeEnabled: boolean; confirmed: boolean; approval: MergeApproval }): MergeDecision {
  if (!input.mergeEnabled) {
    return {
      callApi: false,
      error: { code: "merge_disabled", message: "La fusión está apagada.", retryAfterMs: null },
    }
  }
  if (!input.confirmed) {
    return {
      callApi: false,
      error: { code: "needs_confirmation", message: "Hace falta una confirmación explícita.", retryAfterMs: null },
    }
  }
  if (input.approval.decision === "denied") {
    return {
      callApi: false,
      error: { code: "merge_denied", message: input.approval.reason, retryAfterMs: null },
    }
  }
  if (input.approval.decision !== "granted") {
    return {
      callApi: false,
      error: { code: "needs_approval", message: "La regla require_approval todavía no concedió la fusión.", retryAfterMs: null },
    }
  }
  return { callApi: true, error: null }
}

export async function performMerge<T>(input: {
  mergeEnabled: boolean
  confirmed: boolean
  gate: ApprovalGate
  request: Parameters<ApprovalGate["review"]>[0]
  send: () => Promise<T>
}): Promise<{ ok: true; value: T } | { ok: false; error: CiError }> {
  const approval = await input.gate.review({ ...input.request, confirmed: input.confirmed })
  const decision = decideMerge({ mergeEnabled: input.mergeEnabled, confirmed: input.confirmed, approval })
  if (!decision.callApi || decision.error) {
    return { ok: false, error: decision.error ?? { code: "needs_approval", message: "Sin aprobación.", retryAfterMs: null } }
  }
  return { ok: true, value: await input.send() }
}

/**
 * Port for the guard-rule engine (RUI-TOOLS-001 / require_approval).
 * The real engine is not in this repo yet. This adapter never grants a merge
 * unless the caller passes an explicit confirmation and a person id.
 * Passing checks is not approval.
 */

export type MergeApprovalRequest = {
  owner: string
  repo: string
  pullNumber: number
  sha: string
  confirmed: boolean
  grantedBy?: string
}

export type MergeApproval =
  | { decision: "required" }
  | { decision: "granted"; grantedBy: string }
  | { decision: "denied"; reason: string }

export type ApprovalGate = {
  review(request: MergeApprovalRequest): Promise<MergeApproval> | MergeApproval
}

export function alwaysAskApproval(): ApprovalGate {
  return {
    review(request) {
      if (request.confirmed && request.grantedBy && request.grantedBy.trim()) {
        return { decision: "granted", grantedBy: request.grantedBy.trim() }
      }
      return { decision: "required" }
    },
  }
}

/**
 * Connection point for a fix timeline. This module does not run an agent.
 * The host publishes steps. The UI subscribes.
 */

export type AgentFixEvent = {
  id: string
  kind: "thought" | "edit" | "test" | "push" | "done"
  label: string
  files?: readonly string[]
  at: string
}

export type AgentFixPort = {
  publish(event: AgentFixEvent): void
  subscribe(listener: (event: AgentFixEvent) => void): () => void
  snapshot(): readonly AgentFixEvent[]
}

export function createAgentFixPort(): AgentFixPort {
  const events: AgentFixEvent[] = []
  const listeners = new Set<(event: AgentFixEvent) => void>()
  return {
    publish(event) {
      events.push(event)
      for (const listener of listeners) listener(event)
    },
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    snapshot() {
      return events.slice()
    },
  }
}

export type CheckFailedNotice = {
  id: string
  name: string
  url: string | null
}

/** The host decides what to publish. This only forwards a failure notice. */
export function notifyCheckFailed(handler: ((check: CheckFailedNotice) => void) | undefined, check: CheckFailedNotice) {
  handler?.(check)
}

const SECRET_KEYS = new Set([
  "token",
  "access_token",
  "authorization",
  "webhook_secret",
  "secret",
  "password",
  "github_token",
])

/** Drops credential-shaped fields before a payload is sent to the browser. */
export function stripSecrets(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stripSecrets)
  if (!value || typeof value !== "object") return value
  const next: Record<string, unknown> = {}
  for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
    if (SECRET_KEYS.has(key.toLowerCase())) continue
    next[key] = stripSecrets(child)
  }
  return next
}
